package br.com.admeclesial.application.sacramento;
import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial;
import br.com.admeclesial.domain.pessoa.*; import br.com.admeclesial.domain.sacramento.*; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import br.com.admeclesial.infrastructure.persistence.sacramento.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ParticipanteSacramentoApplicationServiceTest { @Mock ParticipanteSacramentoRepository repository; @Mock SacramentoRepository sacramentoRepository; @Mock PessoaRepository pessoaRepository; ParticipanteSacramentoApplicationService service; Sacramento s; Pessoa p; UUID su,pu;
 @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new ParticipanteSacramentoApplicationService(repository,sacramentoRepository,pessoaRepository);s=new Sacramento();var organizacao=new OrganizacaoEclesial();s.setOrganizacaoEclesial(organizacao);p=new Pessoa();su=UUID.randomUUID();pu=UUID.randomUUID();try{java.lang.reflect.Field fo=OrganizacaoEclesial.class.getDeclaredField("uuid");fo.setAccessible(true);fo.set(organizacao,UUID.randomUUID());java.lang.reflect.Field fs=Sacramento.class.getDeclaredField("id");fs.setAccessible(true);fs.set(s,1L);java.lang.reflect.Field fp=Pessoa.class.getDeclaredField("id");fp.setAccessible(true);fp.set(p,2L);}catch(Exception e){throw new RuntimeException(e);}when(sacramentoRepository.findByUuid(su)).thenReturn(Optional.of(s));when(pessoaRepository.findByUuid(pu)).thenReturn(Optional.of(p));when(repository.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void deveCriar(){var r=service.criar(new ParticipanteSacramentoRequest(su,pu,TipoParticipacaoSacramento.SACRAMENTANDO," ok "));assertEquals(TipoParticipacaoSacramento.SACRAMENTANDO,r.tipoParticipacao());assertEquals("ok",r.observacao());}
 @Test void naoDeveIncluirEmCancelado(){s.setStatus(StatusSacramento.CANCELADO);var ex=assertThrows(SacramentoBusinessException.class,()->service.criar(new ParticipanteSacramentoRequest(su,pu,TipoParticipacaoSacramento.SACRAMENTANDO,null)));assertTrue(ex.getMessage().contains("cancelado"));}
 @Test void naoDeveIncluirPessoaInativa(){p.setAtivo(false);var ex=assertThrows(SacramentoBusinessException.class,()->service.criar(new ParticipanteSacramentoRequest(su,pu,TipoParticipacaoSacramento.SACRAMENTANDO,null)));assertTrue(ex.getMessage().contains("inativa"));}
 @Test void naoDeveDuplicarParticipacao(){when(repository.existsBySacramentoIdAndPessoaIdAndTipoParticipacao(anyLong(),anyLong(),any())).thenReturn(true);var ex=assertThrows(SacramentoBusinessException.class,()->service.criar(new ParticipanteSacramentoRequest(su,pu,TipoParticipacaoSacramento.SACRAMENTANDO,null)));assertTrue(ex.getMessage().contains("já possui"));}
}
